#!/usr/bin/env python3
"""Run the invocations generated by generate_invocations.py.

Each invocation is executed in its own temporary directory, into which the model
files referenced by the command are copied first. The combined output (stdout and
stderr) of the command is written to the log file of the invocation.
"""

import argparse
import json
import os
import shlex
import shutil
import signal
import subprocess
import sys
import tempfile
import time
from pathlib import Path

from commands import CMD_KEYS, FILE_KEYS, PLACEHOLDER, pick_command, placeholders

SCRIPT_DIR = Path(__file__).resolve().parent
ROOT = SCRIPT_DIR.parent
BENCHMARK_DIR = ROOT / "benchmarks"

# Seconds to wait for a killed process to actually terminate.
KILL_GRACE = 5


class NotApplicable(Exception):
    """The configuration cannot be run on the benchmark, so there is nothing to do."""


def substitute(cmd, values):
    """Substitute the placeholders in a command line, yielding a list of arguments.

    A placeholder without a value makes its argument disappear; if that argument was
    preceded by an option, the option disappears as well. This way a benchmark
    without constants gets no '--constants' argument at all.
    """
    args = []
    for token in shlex.split(cmd):
        names = PLACEHOLDER.findall(token)
        if any(values.get(n) is None for n in names):
            if args and args[-1].startswith("-"):
                args.pop()
            continue
        args.append(PLACEHOLDER.sub(lambda m: values[m.group(1)], token))
    return args


def resolve_binary(bin):
    """The absolute path of the tool binary."""
    path = Path(os.path.expanduser(bin))
    if not path.is_absolute():
        if len(path.parts) == 1:
            found = shutil.which(str(path))
            if found:
                return Path(found)
        path = ROOT / path
    return path


def prepare(invocation):
    """The binary, the command line and the model files of an invocation.

    Raises NotApplicable if the configuration does not fit the benchmark and
    ValueError if the invocation is broken in some other way.
    """
    config, benchmark = invocation["config"], invocation["benchmark"]
    cmd = pick_command(config, benchmark)
    if cmd is None:
        raise NotApplicable(f"configuration '{config['id']}' is not applicable to "
                            f"benchmark '{benchmark['id']}'")
    binary = resolve_binary(config["bin"])
    if not binary.is_file():
        raise ValueError(f"binary not found: {binary}")
    files = {}
    for name in placeholders(cmd):
        if name in FILE_KEYS and name in benchmark:
            source = BENCHMARK_DIR / benchmark[name]
            if not source.is_file():
                raise ValueError(f"model file not found: {source}")
            files[name] = source
    return binary, cmd, files


def execute(args, cwd, timelimit):
    """Run a command, aborting it when it exceeds the time limit.

    Returns (output, wall_time, return_code); the return code is None on a timeout.
    """
    start = time.time()
    # Own session, so that the whole process tree can be killed on a timeout.
    proc = subprocess.Popen(args, cwd=cwd, stdin=subprocess.DEVNULL,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                            start_new_session=True)
    timeout = False
    try:
        try:
            output, _ = proc.communicate(timeout=timelimit)
        except subprocess.TimeoutExpired:
            timeout = True
            output = terminate(proc)
    except KeyboardInterrupt:
        terminate(proc)
        raise
    wall_time = time.time() - start
    return output.decode("utf8", errors="replace"), wall_time, None if timeout else proc.returncode


def terminate(proc):
    """Kill the process tree of proc and return whatever output it produced."""
    for sig in (signal.SIGTERM, signal.SIGKILL):
        try:
            os.killpg(proc.pid, sig)
        except ProcessLookupError:
            break
        try:
            output, _ = proc.communicate(timeout=KILL_GRACE)
            return output
        except subprocess.TimeoutExpired:
            continue
    try:
        output, _ = proc.communicate(timeout=KILL_GRACE)
    except subprocess.TimeoutExpired:
        output = b""
    return output


def run(invocation):
    """Run a single invocation and write its log file. Returns a status string."""
    config, benchmark = invocation["config"], invocation["benchmark"]
    log = Path(invocation["log"])
    timelimit = invocation["timelimit"]

    try:
        binary, cmd, files = prepare(invocation)
    except NotApplicable as e:
        return "skipped", 0.0, str(e)
    except ValueError as e:
        log.write_text(f"Error:\t{e}\n")
        return "error", 0.0, str(e)

    log.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="invocation-") as tmp:
        values = {k: v for k, v in benchmark.items() if k not in ("id", "type")}
        for name, source in files.items():
            shutil.copy2(source, Path(tmp) / source.name)
            values[name] = source.name
        args = [str(binary)] + substitute(cmd, values)
        output, wall_time, return_code = execute(args, tmp, timelimit)

    header = (f"Command:\t{shlex.join(args)}\n"
              f"Benchmark:\t{benchmark['id']}\n"
              f"Configuration:\t{config['id']}\n"
              f"Repetition:\t{invocation.get('repetition', 1)}\n"
              f"Time limit:\t{timelimit}\n"
              f"Output:\n")
    footer = f"\n{'-' * 40}\nWallclock time:\t{wall_time:.3f}\nReturn code:\t{return_code}\n"
    if return_code is None:
        footer += (f"Computation aborted after {wall_time:.3f} seconds since the time limit "
                   f"of {timelimit} seconds was exceeded.\n")
    log.write_text(header + output + footer)

    if return_code is None:
        return "timeout", wall_time, None
    if return_code != 0:
        return "error", wall_time, f"return code {return_code}"
    return "ok", wall_time, None


def main():
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("invocations", help="json file as written by generate_invocations.py")
    parser.add_argument("--entry", type=int, metavar="I",
                        help="run only the I-th invocation (1-based, as numbered in the output)")
    parser.add_argument("--dry-run", action="store_true",
                        help="only show what would be run, do not execute anything")
    args = parser.parse_args()

    with open(args.invocations) as f:
        invocations = json.load(f)
    if not isinstance(invocations, list):
        sys.exit(f"{args.invocations}: expected a JSON array")

    selected = list(enumerate(invocations, start=1))
    if args.entry is not None:
        if not 1 <= args.entry <= len(invocations):
            sys.exit(f"--entry must be between 1 and {len(invocations)}, got {args.entry}")
        selected = [selected[args.entry - 1]]

    if args.dry_run:
        for _, invocation in selected:
            try:
                binary, cmd, files = prepare(invocation)
            except NotApplicable as e:
                print(f"skipped: {e}")
                continue
            except ValueError as e:
                print(f"! {e}")
                continue
            values = {k: v for k, v in invocation["benchmark"].items() if k not in ("id", "type")}
            values.update({n: s.name for n, s in files.items()})
            print(f"{invocation['log']}: {shlex.join([str(binary)] + substitute(cmd, values))}")
        return

    counts = {"ok": 0, "timeout": 0, "error": 0, "skipped": 0}
    width = len(str(len(invocations)))
    for number, invocation in selected:
        label = f"{invocation['config']['id']} {invocation['benchmark']['id']}"
        if "repetition" in invocation:
            label += f" rep{invocation['repetition']}"
        print(f"[{number:>{width}}/{len(invocations)}] {label} ... ", end="", flush=True)
        try:
            status, wall_time, note = run(invocation)
        except KeyboardInterrupt:
            print("interrupted")
            sys.exit("aborted")
        counts[status] += 1
        print(f"{status} ({wall_time:.1f}s)" + (f": {note}" if note else ""), flush=True)

    print(f"\n{len(selected)} invocations: "
          f"{counts['ok']} ok, {counts['timeout']} timeout, {counts['error']} error, "
          f"{counts['skipped']} skipped")


if __name__ == "__main__":
    main()
